/* Module: js/storage.js */
/**
 * storage.js — Mentorix Storage Layer
 * Extracted from mentorix_v2_4.html — Stage 3 of SPA modularization.
 * Migrated to IndexedDB to overcome the 5MB browser storage ceiling.
 *
 * Owns all IndexedDB read/write operations for user state, and localStorage fallbacks.
 * All keys in IndexedDB use the pattern: {uid}_{dataKey}
 * Non-user state keys (like profiles list, sessions) still use localStorage 'mx3_'.
 *
 * Dependencies (globals):
 *   D        — application state object (defined in main script)
 *   toast()  — from helpers.js
 *   getSession() — from auth functions in main script
 *
 * Backward compatibility: automatic migration from localStorage on first load.
 */

'use strict';

if (typeof window !== 'undefined' && window.LS === undefined) {
  window.LS = null;
}

/* ── INDEXEDDB LOW-LEVEL UTILITIES ───────────────────────────── */

const DB_NAME = 'mentorix_db';
const STORE_NAME = 'user_state';

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = (e) => resolve(e.target.result);
    request.onerror = (e) => reject(e.target.error);
  });
}

function idbGet(key) {
  return openDB().then((db) => {
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(key);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  });
}

function idbSet(key, value) {
  return openDB().then((db) => {
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(value, key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  });
}

function idbDel(key) {
  return openDB().then((db) => {
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  });
}

/* ── LOW-LEVEL LOCALSTORAGE PRIMITIVES (Non-user specific state) ── */

/**
 * Write a value to localStorage under key 'mx3_{k}'.
 */
const sv = (k, v) => {
  try {
    localStorage.setItem('mx3_' + k, JSON.stringify(v));
  } catch (e) {
    console.error('[Mentorix] localStorage write failed for key:', k, e);
  }
};

/**
 * Read a value from localStorage under key 'mx3_{k}'.
 * Returns fallback `fb` if the key is missing or the value is unreadable.
 */
const ld = (k, fb) => {
  try {
    const v = localStorage.getItem('mx3_' + k);
    return v != null ? JSON.parse(v) : fb;
  } catch {
    return fb;
  }
};

/* ── PER-USER PERSISTENCE ───────────────────────────────────── */

/** All keys that belong to a user's persisted state. */
const USER_DATA_KEYS = [
  'profile', 'xp', 'streak', 'lastStudy', 'badges', 'topics',
  'chatMsgs', 'exploredCats', 'settings', 'memory', 'notes',
  'roadmaps', 'courses'
];

/**
 * Load all persisted data for a user into the D state object.
 * Checks IndexedDB first. If missing, attempts auto-migration from localStorage.
 * @param {string} uid — user ID from session
 * @returns {Promise}
 */
async function loadUserData(uid) {
  const migrations = USER_DATA_KEYS.map(async (k) => {
    try {
      let val = await idbGet(`${uid}_${k}`);
      if (val !== undefined) {
        D[k] = val;
      } else {
        // Auto-migrate from localStorage if found
        const localKey = `mx3_${uid}_${k}`;
        const localValStr = localStorage.getItem(localKey);
        if (localValStr !== null) {
          try {
            const localVal = JSON.parse(localValStr);
            D[k] = localVal;
            // Persist to IndexedDB
            await idbSet(`${uid}_${k}`, localVal);
            // Clean up localStorage to free space
            localStorage.removeItem(localKey);
          } catch (err) {
            console.error(`[Mentorix] Failed to parse localStorage value for key ${localKey}`, err);
          }
        }
      }
    } catch (e) {
      console.error(`[Mentorix] Failed to load key ${k} from IndexedDB`, e);
    }
  });

  await Promise.all(migrations);

  // Deep Integration with PSDE Engine
  if (window.PSDE) {
    try {
      const psdeStudent = await window.PSDE.LoadStudent(uid);
      if (!psdeStudent) {
        await window.PSDE.CreateStudent({ studentId: uid, name: D.profile?.name || 'Aspirant', email: D.profile?.email || `${uid}@student.mentorix.ai` });
      }
      const history = await window.PSDE.LoadAcademicHistory(uid);
      if (history && history.length > 0) {
        D.academicHistory = history;
      }
      const achievements = await window.PSDE.LoadAchievements(uid);
      if (achievements) {
        D.xp = achievements.xp || D.xp;
        D.level = achievements.level || D.level;
        D.badges = achievements.badges || D.badges;
      }
      const tioMem = await window.PSDE.LoadTioMemoryRefs(uid);
      if (tioMem) {
        D.tioMemoryRefs = tioMem;
      }
    } catch (err) {
      console.warn('[PSDE] Integration load warning:', err);
    }
  }
}

/**
 * Persist all D state keys for the currently logged-in user.
 * Reads the session to get the uid. No-ops if no session exists.
 * @returns {Promise}
 */
async function saveUserData() {
  const s = getSession();
  if (!s?.id) return;
  const saves = USER_DATA_KEYS.map(k => idbSet(`${s.id}_${k}`, D[k]));
  try {
    await Promise.all(saves);
  } catch (e) {
    console.error('[Mentorix] Failed to save user data to IndexedDB:', e);
  }

  // Deep Integration with PSDE Engine
  if (window.PSDE) {
    try {
      await window.PSDE.SaveAchievements({
        xp: D.xp || 0,
        level: D.level || 1,
        badges: D.badges || [],
        milestones: D.milestones || []
      }, s.id);
      await window.PSDE.SavePreference({
        theme: D.settings?.theme || 'dark',
        learningStyle: D.settings?.learningStyle || 'visual'
      }, s.id);
    } catch (err) {
      console.warn('[PSDE] Integration save warning:', err);
    }
  }
}

/**
 * Remove all IndexedDB and localStorage data for a given user ID.
 * Used by account deletion / full reset flows.
 * @param {string} uid — user ID to clear
 * @returns {Promise}
 */
async function clearUserData(uid) {
  const deletes = USER_DATA_KEYS.map(k => {
    localStorage.removeItem(`mx3_${uid}_${k}`);
    return idbDel(`${uid}_${k}`);
  });
  await Promise.all(deletes);
}

/* ── DEBOUNCED SAVE ─────────────────────────────────────────── */

/**
 * Debounced save — batches rapid successive calls at 300ms.
 * Safe to call from addXP, addTopic, checkStreak, etc.
 * Use saveNow() where immediate persistence is required.
 */
let _saveTimer = null;

function saveAll() {
  clearTimeout(_saveTimer);
  _saveTimer = setTimeout(saveUserData, 300);
}

/**
 * Immediate save — flushes any pending debounced save and persists now.
 * Use in: logout, onboarding completion, course generation.
 */
function saveNow() {
  clearTimeout(_saveTimer);
  saveUserData();
}

/* ── FLUSH ON TAB CLOSE / BACKGROUND ────────────────────────── */
/* The 300ms debounce in saveAll() means a tab closed immediately after
   an action (e.g. completing a quiz, then instantly closing the tab)
   could lose that final write. Flush any pending save when the page
   is about to be hidden or unloaded, covering both desktop tab-close
   and mobile app-backgrounding (visibilitychange fires reliably on
   mobile; beforeunload often does not). */
window.addEventListener('pagehide', () => { if (_saveTimer) saveNow(); });
window.addEventListener('visibilitychange', () => {
  if (document.hidden && _saveTimer) saveNow();
});

/* ── EXPORTS ────────────────────────────────────────────────── */
window.sv            = sv;
window.ld            = ld;
window.USER_DATA_KEYS = USER_DATA_KEYS;
window.loadUserData  = loadUserData;
window.saveUserData  = saveUserData;
window.clearUserData = clearUserData;
window.saveAll       = saveAll;
window.saveNow       = saveNow;


/* Module: js/state/eventBus.js */
/**
 * eventBus.js — Universal Decoupled Event Bus Engine
 * Phase P4 (Universal State & Update Architecture)
 *
 * Enables loose coupling between feature modules:
 * Nobody directly calls anybody. Modules publish & subscribe to events.
 * Example: Lesson Completed -> Event -> Dashboard / Progress / Revision Queue
 */

'use strict';

(function(exports) {

  class EventBus {
    constructor() {
      this.listeners = new Map();
    }

    subscribe(eventName, callback) {
      if (!eventName || typeof callback !== 'function') return () => {};

      if (!this.listeners.has(eventName)) {
        this.listeners.set(eventName, new Set());
      }
      this.listeners.get(eventName).add(callback);

      // Return unsubscribe function
      return () => this.unsubscribe(eventName, callback);
    }

    unsubscribe(eventName, callback) {
      if (!this.listeners.has(eventName)) return;
      this.listeners.get(eventName).delete(callback);
    }

    publish(eventName, payload = {}) {
      if (!eventName || !this.listeners.has(eventName)) return;

      const subscribers = this.listeners.get(eventName);
      subscribers.forEach(callback => {
        try {
          callback(payload);
        } catch (e) {
          console.warn(`[EventBus] Subscriber error for event "${eventName}":`, e);
        }
      });

      // Notify stateDebugger if active
      const sd = typeof window !== 'undefined' ? window.StateDebugger : null;
      if (sd && typeof sd.logEvent === 'function') {
        sd.logEvent(eventName, payload);
      }
    }
  }

  const instance = new EventBus();
  if (typeof window !== 'undefined') window.EventBus = instance;
  exports.EventBus = instance;

})(typeof exports !== 'undefined' ? exports : window);


/* Module: js/state/stateManager.js */
/**
 * stateManager.js — Universal State Manager Orchestrator
 * Phase P4 (Universal State & Update Architecture)
 *
 * Central coordinator for all application state in Mentorix:
 * User Action -> Validation -> State Manager -> Affected Module -> Render Pipeline -> UI Update
 *
 * Enforces strict 5-domain state separation:
 * 1. UI State (Temporary: modal open, sidebar, dropdowns)
 * 2. Session State (Active activity: learning paragraph, exam question, timer)
 * 3. Application State (Shared: theme, language, active screen, navigation)
 * 4. User State (Long-term: preferences, progress, badges, XP)
 * 5. Server State (Backend: PYQ metadata, leaderboard, syllabus)
 */

'use strict';

(function(exports) {

  class StateManager {
    constructor() {
      this.initialized = false;
    }

    init() {
      if (this.initialized) return;

      this.initialized = true;

      // Restore interrupted session automatically if available
      let sp = typeof window !== 'undefined' ? window.StatePersistence : null;
      if (typeof require !== 'undefined' && !sp) {
        try { sp = require('./statePersistence.js').StatePersistence; } catch(e){}
      }
      if (sp && typeof sp.restoreInterruptedSession === 'function') {
        const restored = sp.restoreInterruptedSession();
        if (restored) {
          const ssm = typeof window !== 'undefined' ? window.SessionStateManager : null;
          if (ssm && typeof ssm.startSession === 'function') {
            ssm.startSession(restored.type, restored.data);
          }
        }
      }
    }

    validateStateMutation(domain, payload) {
      if (!domain || !payload) return false;
      
      // Basic schema validations (Section 10)
      if (domain === 'user' && payload.xpAdd !== undefined && (typeof payload.xpAdd !== 'number' || payload.xpAdd < 0)) {
        console.warn('[StateManager] Invalid XP payload:', payload);
        return false;
      }
      if (domain === 'session' && payload.topic && typeof payload.topic !== 'string') {
        console.warn('[StateManager] Invalid session topic payload:', payload);
        return false;
      }

      return true;
    }

    applyStateUpdate(domain, payload, options = {}) {
      if (!domain || !payload) return;

      // Section 10: Validation Layer — Pre-mutation verification
      if (!this.validateStateMutation(domain, payload)) {
        console.warn(`[StateManager] Pre-mutation validation failed for domain "${domain}"`);
        return;
      }

      let sr = typeof window !== 'undefined' ? window.StateRegistry : null;
      let ssm = typeof window !== 'undefined' ? window.SessionStateManager : null;
      let asm = typeof window !== 'undefined' ? window.ApplicationStateManager : null;
      let usm = typeof window !== 'undefined' ? window.UserStateManager : null;
      let sd = typeof window !== 'undefined' ? window.StateDebugger : null;

      if (typeof require !== 'undefined') {
        if (!sr) try { sr = require('./stateRegistry.js').StateRegistry; } catch(e){}
        if (!ssm) try { ssm = require('./sessionStateManager.js').SessionStateManager; } catch(e){}
        if (!asm) try { asm = require('./applicationStateManager.js').ApplicationStateManager; } catch(e){}
        if (!usm) try { usm = require('./userStateManager.js').UserStateManager; } catch(e){}
        if (!sd) try { sd = require('./stateDebugger.js').StateDebugger; } catch(e){}
      }

      // Log to debugger
      if (sd && typeof sd.logStateUpdate === 'function') {
        sd.logStateUpdate(domain, payload, options.source || 'UserAction');
      }

      // Route update to respective state domain manager
      switch (domain) {
        case 'session':
          if (ssm && typeof ssm.updateSessionData === 'function') {
            ssm.updateSessionData(payload);
          }
          break;
        case 'application':
          if (asm) {
            Object.keys(payload).forEach(k => asm.set(k, payload[k]));
          }
          break;
        case 'user':
          if (usm && payload.xpAdd) {
            usm.addXP(payload.xpAdd);
          }
          break;
        default:
          break;
      }
    }
  }

  const instance = new StateManager();
  if (typeof window !== 'undefined') window.StateManager = instance;
  exports.StateManager = instance;

})(typeof exports !== 'undefined' ? exports : window);


/* Module: js/router.js */
/**
 * router.js — Mentorix Client-Side Router
 * Extracted from mentorix_v2_4.html — Stage 5 of SPA modularization.
 *
 * Owns: go(), renderScr(), browser history, popstate, swipe gestures,
 *       keyboard shortcut nav, screen-change analytics stub.
 *
 * Dependencies (globals):
 *   D                — application state
 *   SCREEN_TITLES    — constants.js
 *   renderAuth       — auth.js
 *   updateSB, buildMobileNav, closeMobDrawer — main script
 *   rDash, rCourses, rRecovery, rNotebook, rRevision,
 *   rExplore, rCareers, rRoadmap, rTests, rDoubt,
 *   rProgress, rSettings, rMentor, rLearn — screen modules
 */

'use strict';

/* ── SCREEN REGISTRY ────────────────────────────────────────── */

const SCREEN_MAP = {
  dash:     () => { if (typeof rDash === 'function') { rDash(); return true; } return false; },
  courses:  () => { if (typeof rCourses === 'function') { rCourses(); return true; } return false; },
  recovery: () => { if (typeof rRecovery === 'function') { rRecovery(); return true; } return false; },
  notebook: () => { if (typeof rNotebook === 'function') { rNotebook(); return true; } return false; },
  revision: () => { if (typeof rRevision === 'function') { rRevision(); return true; } return false; },
  explore:  () => { if (typeof rExplore === 'function') { rExplore(); return true; } return false; },
  careers:  () => { if (typeof rCareers === 'function') { rCareers(); return true; } return false; },
  roadmap:  () => { if (typeof rRoadmap === 'function') { rRoadmap(); return true; } return false; },
  tests:    () => { if (typeof rTests === 'function') { rTests(); return true; } return false; },
  doubt:    () => { if (typeof rDoubt === 'function') { rDoubt(); return true; } return false; },
  progress: () => { if (typeof rProgress === 'function') { rProgress(); return true; } return false; },
  settings: () => { if (typeof rSettings === 'function') { rSettings(); return true; } return false; },
  mentor:   () => { if (typeof rMentor === 'function') { rMentor(); return true; } return false; },
  learn:    () => { if (typeof rLearn === 'function') { rLearn(); return true; } return false; },
  comp:     () => { if (typeof rComp === 'function') { rComp(); return true; } return false; },
  qiacp:    () => {
    const fn = typeof renderQIACP === 'function' ? renderQIACP : (typeof window.renderQIACP === 'function' ? window.renderQIACP : null);
    if (fn) { fn(); return true; }
    return false;
  }
};

/* ── CANONICAL IA ROUTE REGISTRY ────────────────────────────── */

const CANONICAL_ROUTES = {
  'dash': '/dash',
  'courses': '/courses',
  'comp': '/comp',
  'mentor': '/mentor',
  'settings': '/profile',
  'notebook': '/notebook',
  'revision': '/revision',
  'progress': '/progress',
  'explore': '/explore'
};

/* ── MAIN ROUTING FUNCTION ──────────────────────────────────── */

function go(scr, param) {
  // Ensure main application shell container is initialized before rendering screen
  if (!document.getElementById('main')) {
    if (typeof initApp === 'function' && typeof getSession === 'function' && getSession()) {
      initApp();
    } else if (typeof continueAsGuest === 'function') {
      continueAsGuest();
      return;
    }
  }
  // Execute unmount lifecycle cleanup for previous screen
  if (typeof window.onScreenUnmount === 'function') {
    try {
      window.onScreenUnmount();
    } catch (e) {
      console.warn('[Router Unmount] Error during screen cleanup:', e);
    }
    window.onScreenUnmount = null;
  }

  // UNIA Navigation Engine Integration
  if (window.NavigationEngine && typeof window.NavigationEngine.navigate === 'function') {
    window.NavigationEngine.navigate(scr, param);
  }

  // Preserve navigation context & cross-device session snapshot
  if (window.WorkspaceResumeManager) window.WorkspaceResumeManager.saveWorkspaceSnapshot();
  if (window.TioEngine?.ObservationEngine) {
    window.TioEngine.ObservationEngine.observeAction('SCREEN_NAVIGATED', { screen: scr, param });
  }
  if (window.UAESEngine) window.UAESEngine.saveSessionSnapshot();
  if (window.UASCAEngine) window.UASCAEngine.onNavigate(scr);
  if (window.ASLAEngine) window.ASLAEngine.onNavigate(scr);
  if (window.UDFIAEngine) window.UDFIAEngine.publish('Interface.NavigationChanged', { screen: scr, param });
  if (!window.D._navContext) window.D._navContext = {};
  if (D.screen && document.getElementById('main')) {
    window.D._navContext[D.screen] = {
      scrollTop: document.getElementById('main').scrollTop || 0,
      timestamp: Date.now()
    };
  }

  // Stop any active lesson sub-cycle
  const learnSub = document.getElementById('learn-sub');
  if (learnSub && learnSub._cycleStop) learnSub._cycleStop();

  D.screen = scr;
  if (param !== undefined) D._param = param;
  document.body.setAttribute('data-screen', scr);

  // Sync mobile bottom navigation bar active state
  const bnavItems = document.querySelectorAll('#mx-bottom-nav .mx-bnav-item');
  const targetScreen = scr === 'dash' ? 'dashboard' : scr;
  bnavItems.forEach(item => {
    if (item.getAttribute('data-screen') === targetScreen) {
      item.classList.add('active');
    } else {
      item.classList.remove('active');
    }
  });

  // Sync hash deep-link URL
  const routePath = CANONICAL_ROUTES[scr] || `/${scr}`;
  const hashTarget = `#${routePath}${param ? '/' + encodeURIComponent(param) : ''}`;
  if (window.history?.pushState) {
    if (window.location.hash !== hashTarget) {
      window.history.pushState({ screen: scr, param }, '', hashTarget);
    }
  }

  // Close mobile drawer if open
  if (typeof closeMobDrawer === 'function') closeMobDrawer();
  if (typeof updateSB       === 'function') updateSB();
  if (typeof buildMobileNav === 'function') buildMobileNav();

  // Step 10 — spring page transition
  const main = document.getElementById('main');
  if (main) {
    // Exit: fade + slide up
    main.style.opacity    = '0';
    main.style.transform  = 'translateY(8px) scale(0.997)';
    main.style.transition = 'opacity 90ms var(--ease-exit), transform 90ms var(--ease-exit)';

    setTimeout(() => {
      renderScr();

      // Restore scroll position if present in nav context
      const prevContext = window.D._navContext[scr];
      if (prevContext && prevContext.scrollTop) {
        main.scrollTop = prevContext.scrollTop;
      } else {
        main.scrollTop = 0;
      }

      // Enter: spring slide down
      main.style.transition = 'opacity 240ms var(--ease-smooth), transform 240ms var(--spring-settle,cubic-bezier(.34,1.3,.64,1))';
      main.style.opacity    = '1';
      main.style.transform  = 'translateY(0) scale(1)';

      // ASMR: play navigation sound
      if (typeof MxAudio !== 'undefined') MxAudio.tuck();

      // A11y: announce screen change
      const ann = document.getElementById('a11y-announce');
      if (ann) ann.textContent = SCREEN_TITLES[scr] || scr;

      // Focus management
      requestAnimationFrame(() => {
        const h = main.querySelector('h1,h2,[data-focus-first]');
        if (h) { h.setAttribute('tabindex', '-1'); h.focus({ preventScroll: true }); }
        if (window.TioOrchestrator) window.TioOrchestrator.updateState();
      });
    }, 90);
  } else {
    renderScr();
  }
}

/* ── SCREEN RENDERER ────────────────────────────────────────── */

const GATED_SCREENS = ['courses', 'careers', 'tests', 'revision', 'progress', 'roadmap'];

function renderPoliteOnboardingPrompt() {
  const main = document.getElementById('main');
  if (!main) return;
  main.innerHTML = `
    <div class="sw scr page-enter" style="max-width:580px;margin:50px auto;text-align:center">
      <div style="background:rgba(139,92,246,0.1);border:1px solid rgba(139,92,246,0.3);border-radius:24px;padding:40px 28px;box-shadow:0 12px 40px rgba(0,0,0,0.4)">
        <div style="font-size:56px;margin-bottom:16px">🎯</div>
        <div class="h1" style="color:#fff;margin-bottom:10px;font-size:28px">Let's Personalize Your Mentorix</div>
        <p class="sub" style="font-size:14px;line-height:1.65;margin-bottom:28px;max-width:460px;margin-left:auto;margin-right:auto">
          We need to understand your grade, board, and learning goals first so Mentorix can personalize your courses, quizzes, and career paths for you.
        </p>
        <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap">
          <button class="btn bpri blg" onclick="if(typeof renderOB==='function')renderOB()" style="padding:14px 28px;font-size:15px;border-radius:14px;box-shadow:0 8px 24px rgba(139,92,246,0.4)">
            🚀 Personalize My Profile (60s)
          </button>
          <button class="btn bgh blg" onclick="go('explore')" style="padding:14px 20px;font-size:14px;border-radius:14px">
            ← Explore Public Content
          </button>
        </div>
      </div>
    </div>
  `;
}

/**
 * Calls the correct render function for D.screen.
 * Dynamic module loading via ModuleRegistry ensures on-demand fetching for un-cached screens.
 */
function renderScr() {
  if (GATED_SCREENS.includes(D.screen) && window.ProfileEngine && !window.ProfileEngine.isPersonalized()) {
    renderPoliteOnboardingPrompt();
    return;
  }

  const currentScr = D.screen || 'dash';
  const fn = SCREEN_MAP[currentScr];

  let success = false;
  if (fn) {
    try {
      success = fn();
    } catch (e) {
      console.warn(`[Router] Screen render exception for '${currentScr}':`, e);
    }
  }

  // If screen function is missing or returned falsy (un-loaded module), lazy load module via ModuleRegistry
  if (!success && window.ModuleRegistry && typeof window.ModuleRegistry.loadModule === 'function') {
    const main = document.getElementById('main');
    if (main) {
      main.innerHTML = `
        <div class="sw scr page-enter" style="max-width:800px;margin:80px auto;text-align:center;padding:40px;">
          <div style="width:36px;height:36px;border:3px solid rgba(139,92,246,0.2);border-top-color:#8b5cf6;border-radius:50%;margin:0 auto 16px;animation:mx-spin 0.8s linear infinite;"></div>
          <p style="color:var(--sub, #94a3b8);font-size:14px;font-weight:500;">Loading Mentorix ${currentScr.toUpperCase()} Module...</p>
        </div>
      `;
    }

    window.ModuleRegistry.loadModule(currentScr).then(() => {
      const loadedFn = SCREEN_MAP[currentScr];
      if (loadedFn) loadedFn();
    }).catch(e => {
      console.warn(`[Router] Module loading fallback failed for '${currentScr}' — falling back to dash:`, e);
      D.screen = 'dash';
      if (typeof rDash === 'function') rDash();
    });
  } else if (!success) {
    console.warn('[Router] Unknown screen:', currentScr, '— falling back to dash');
    D.screen = 'dash';
    if (typeof rDash === 'function') rDash();
  }
}

/* ── BACK BUTTON ────────────────────────────────────────────── */

/**
 * Initialise browser back-button handling via popstate.
 * Uses the {screen} state object pushed by go() for accurate replay.
 */
function initPopstate() {
  window.addEventListener('popstate', e => {
    const target = e.state?.screen || 'dash';
    // Re-route without pushing new history state
    D.screen = target;
    document.body.setAttribute('data-screen', target);
    if (typeof updateSB       === 'function') updateSB();
    if (typeof buildMobileNav === 'function') buildMobileNav();
    renderScr();
  });
}

/* ── SWIPE NAVIGATION ───────────────────────────────────────── */

/**
 * Horizontal swipe between main screens on mobile.
 * Swipe right → go back (popstate); swipe left → go forward (history).
 * Threshold: ≥ 60px horizontal with < 40px vertical drift.
 */
function initSwipe() {
  let tx = 0, ty = 0;
  const main = document.getElementById('main');
  if (!main) return;

  main.addEventListener('touchstart', e => {
    tx = e.touches[0].clientX;
    ty = e.touches[0].clientY;
  }, { passive: true });

  main.addEventListener('touchend', e => {
    const dx = e.changedTouches[0].clientX - tx;
    const dy = e.changedTouches[0].clientY - ty;
    if (Math.abs(dx) < 60 || Math.abs(dy) > 40) return;
    if (dx > 0) {
      window.history.back();
    } else {
      window.history.forward();
    }
  }, { passive: true });
}

/* ── KEYBOARD SHORTCUTS ─────────────────────────────────────── */

/**
 * Global keyboard shortcuts for power users:
 *   Alt + D → Dashboard   Alt + C → Courses    Alt + M → Mentor
 *   Alt + N → Notebook    Alt + R → Revision   Alt + T → Tests
 *   Alt + P → Progress    Alt + S → Settings   Alt + E → Explore
 *   / → open global search
 */
let gSequencePending = false;
let gSequenceTimer = null;

function initKeyboardShortcuts() {
  document.addEventListener('keydown', e => {
    // Skip when typing in inputs
    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName)) return;

    // ? -> Show shortcuts / command palette help
    if (e.key === '?') {
      e.preventDefault();
      if (window.CommandPalette) window.CommandPalette.open();
      return;
    }

    // Esc -> Close top overlay
    if (e.key === 'Escape') {
      if (window.OverlayManager) window.OverlayManager.dismissTopOverlay();
      return;
    }

    // g sequence navigation: g d -> dashboard, g l -> learning, g e -> exams
    if (e.key === 'g' && !e.ctrlKey && !e.metaKey && !e.altKey) {
      gSequencePending = true;
      clearTimeout(gSequenceTimer);
      gSequenceTimer = setTimeout(() => { gSequencePending = false; }, 1000);
      return;
    }

    if (gSequencePending) {
      gSequencePending = false;
      clearTimeout(gSequenceTimer);
      if (e.key === 'd') { go('dash'); return; }
      if (e.key === 'l') { go('courses'); return; }
      if (e.key === 'e') { go('comp'); return; }
    }

    // Global search
    if (e.key === '/' && !e.altKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      if (window.CommandPalette) window.CommandPalette.open();
      else if (typeof openGlobalSearch === 'function') openGlobalSearch();
      return;
    }

    if (!e.altKey) return;
    const map = {
      d: 'dash', c: 'courses', m: 'mentor', n: 'notebook',
      r: 'revision', t: 'tests', p: 'progress', s: 'settings',
      e: 'explore'
    };
    if (map[e.key.toLowerCase()]) {
      e.preventDefault();
      go(map[e.key.toLowerCase()]);
    }
  });
}

/* ── ORIENTATION & VIEWPORT STATE PRESERVATION ──────────────── */

function initOrientationPreservation() {
  const preserveState = () => {
    const main = document.getElementById('main');
    if (main && window.D) {
      if (!window.D._navContext) window.D._navContext = {};
      window.D._navContext[D.screen] = {
        scrollTop: main.scrollTop || 0,
        timestamp: Date.now()
      };
    }
  };

  if (typeof window.addEventListener === 'function') {
    window.addEventListener('orientationchange', preserveState);
    window.addEventListener('resize', () => {
      if (window.detectDeviceHardwareTier) window.detectDeviceHardwareTier();
    });
  }
}

/* ── INITIALISE ─────────────────────────────────────────────── */

initPopstate();
initSwipe();
initKeyboardShortcuts();
initOrientationPreservation();

/* ── EXPORTS ────────────────────────────────────────────────── */
window.go        = go;
window.renderScr = renderScr;
window.registerScreen = () => {};
window.registerScreenMap = () => {};

